import numpy as np
from scipy.optimize import minimize


def construct_packing():
    """
    Construct a specific arrangement of 26 circles in a unit square
    that attempts to maximize the sum of their radii.
    """
    n = 26

    # Multiple diverse initial layouts
    def hex_layout():
        """Hexagonal-ish: 5+4+5+4+5+3 = 26"""
        pts = []
        for x in [0.1, 0.3, 0.5, 0.7, 0.9]:
            pts.append([x, 0.1])
        for x in [0.2, 0.4, 0.6, 0.8]:
            pts.append([x, 0.25])
        for x in [0.1, 0.3, 0.5, 0.7, 0.9]:
            pts.append([x, 0.4])
        for x in [0.2, 0.4, 0.6, 0.8]:
            pts.append([x, 0.55])
        for x in [0.1, 0.3, 0.5, 0.7, 0.9]:
            pts.append([x, 0.7])
        for x in [0.3, 0.5, 0.7]:
            pts.append([x, 0.85])
        return np.array(pts)

    def grid55_layout():
        cols, rows = 5, 5
        xp = np.linspace(0.1, 0.9, cols)
        yp = np.linspace(0.1, 0.9, rows)
        pts = np.array([[x, y] for y in yp for x in xp])
        pts = np.vstack([pts, [0.5, 0.5]])
        return pts

    layouts = [hex_layout(), grid55_layout()]

    def unpack(x):
        c = x.reshape(n, 3)
        return c[:, 0:2], c[:, 2]

    def objective(x):
        c, r = unpack(x)
        penalty = 0.0
        for i in range(n):
            if c[i, 0] < r[i]:
                penalty += (r[i] - c[i, 0]) ** 2
            if c[i, 0] > 1 - r[i]:
                penalty += (c[i, 0] - (1 - r[i])) ** 2
            if c[i, 1] < r[i]:
                penalty += (r[i] - c[i, 1]) ** 2
            if c[i, 1] > 1 - r[i]:
                penalty += (c[i, 1] - (1 - r[i])) ** 2
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt((c[i,0]-c[j,0])**2 + (c[i,1]-c[j,1])**2)
                overlap = r[i] + r[j] - dist
                if overlap > 0:
                    penalty += overlap ** 2
        return -np.sum(r) + 50.0 * penalty

    bounds = []
    for i in range(n):
        bounds.append((0.01, 0.99))
        bounds.append((0.01, 0.99))
        bounds.append((0.01, 0.5))

    best_result = None
    best_obj = np.inf

    for layout in layouts:
        for seed in [42, 123, 7]:
            rng = np.random.RandomState(seed)
            c_init = layout + 0.02 * rng.randn(n, 2)
            c_init = np.clip(c_init, 0.05, 0.95)

            x_init = np.zeros(3 * n)
            for i in range(n):
                x_init[3*i] = c_init[i, 0]
                x_init[3*i+1] = c_init[i, 1]
                x_init[3*i+2] = 0.09

            result = minimize(
                objective, x_init, method='L-BFGS-B', bounds=bounds,
                options={'maxiter': 1500, 'ftol': 1e-12, 'gtol': 1e-10}
            )

            if result.fun < best_obj:
                best_obj = result.fun
                best_result = result

    c_final, r_final = unpack(best_result)

    # Safety clamp
    for i in range(n):
        r_final[i] = min(r_final[i], c_final[i, 0], c_final[i, 1],
                        1 - c_final[i, 0], 1 - c_final[i, 1])
        r_final[i] = max(r_final[i], 0.001)

    # Final overlap fix
    for i in range(n):
        for j in range(i + 1, n):
            dist = np.sqrt((c_final[i,0]-c_final[j,0])**2 + (c_final[i,1]-c_final[j,1])**2)
            if r_final[i] + r_final[j] > dist:
                scale = dist / (r_final[i] + r_final[j]) * 0.999
                r_final[i] *= scale
                r_final[j] *= scale

    for i in range(n):
        r_final[i] = min(r_final[i], c_final[i, 0], c_final[i, 1],
                        1 - c_final[i, 0], 1 - c_final[i, 1])
        r_final[i] = max(r_final[i], 0.001)

    sum_radii = np.sum(r_final)
    return c_final, r_final, sum_radii

