        c = x.reshape(n, 2)
        penalty = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt((c[i,0]-c[j,0])**2 + (c[i,1]-c[j,1])**2)
                overlap = 2 * r_fixed - dist
                if overlap > 0:
                    penalty += overlap ** 2
        # Also penalize being too close to walls
        for i in range(n):
            for val in [c[i,0], c[i,1], 1-c[i,0], 1-c[i,1]]:
                if val < r_fixed:
                    penalty += (r_fixed - val) ** 2
        return penalty

