    centers = np.clip(centers, 0.05, 0.95)

    # Initialize radii small
    radii = np.full(n, 0.05)

    # Iterative radius maximization: repeatedly try to grow each circle
    for iteration in range(200):
        improved = False
        for i in range(n):
            # Max radius for circle i given all others
            max_r = min(centers[i, 0], centers[i, 1],
                       1 - centers[i, 0], 1 - centers[i, 1])
